App.register({group:'pipeline',label:'AI 自动生产',icon:'⌁',routes:[
{path:'pipeline/board',title:'生产调度中心',icon:'⌁',permission:'pipeline',render(){
 const p=App.project();if(!p)return UI.page('AI ORCHESTRATION / FLOW','尚未选择项目','请选择项目后查看生产调度和任务依赖。','',`<div class="card">${UI.empty('没有可用项目','当前身份没有可访问的项目。')}</div>`);
 const started=p.status==='制作中'||p.productionStarted,assetCount=DB.assets.filter(a=>a.tenant===p.tenant&&a.project===p.title).length;
 const stages=DB.stages.map((s,i)=>({...s,state:i===0?(p.brief?'done':'active'):i===1?(p.scriptVersion>1?'done':'active'):i===2?(p.scriptApproved?'done':'active'):i===3?(started?'done':'queued'):i===4?(started?'active':'queued'):i===5?(started?'active':'queued'):'queued',count:i===1?p.episodes+' 集剧本':i===2?'V'+(p.scriptVersion||1)+(p.scriptApproved?' 已确认':' 待审核'):i===3?(p.shotCount||p.episodes*8)+' 个镜头':i===4?assetCount+' 项资产':i===5?(p.done||0)+' / '+p.episodes+' 集':i===6?'待完成 '+Math.max(0,p.episodes-(p.done||0))+' 集':i===7?(p.delivered?'已归档':'待最终审核'):s.count}));
 return UI.page('AI ORCHESTRATION / FLOW','AI 自动生产流水线','当前项目从剧本正式版本到镜头生产单元、音视频资产、质检与交付的自动依赖调度。',started?UI.tag('生产已启动','green'):UI.btn('启动生产计划','production:start','btn-lime'),`
 <div class="notice">AI 生产能力中心是系统执行能力，不是人工部门。生产状态、任务依赖和异常恢复均以当前项目为上下文；当前为演示状态。</div>
 <div class="card section-gap"><div class="card-head"><div><div class="card-title">端到端生产阶段</div><div class="card-sub">当前项目：${UI.esc(p.title)} / ${UI.esc(p.id)}</div></div>${UI.tag(started?'生产运行中':p.status,started?'green':'orange')}</div><div class="pipeline">${stages.map((s,i)=>`<div class="stage ${s.state==='done'?'done':''} ${s.state==='active'?'active':''}"><div class="stage-no">STAGE / 0${i+1}</div><div class="stage-name">${s.name}</div><div class="stage-meta">${s.desc}</div><div class="stage-state">${UI.tag(s.state==='done'?'已完成':s.state==='active'?'执行中':'等待依赖',s.state==='done'?'green':s.state==='active'?'lime':'')}</div><div class="tiny muted" style="margin-top:7px">${s.count}</div></div>`).join('')}</div></div>
 <div class="grid grid-2 section-gap"><div class="card"><div class="card-title">任务依赖关系</div><div class="timeline section-gap">${['正式剧本版本','场次与镜头生产单元拆解','人物 / 场景视觉参考锁定','视频镜头生成与质检','配音 / 配乐 / 字幕合成','整集合成与质量检测','人工最终审核与交付'].map((s,i)=>`<div class="timeline-item"><i class="timeline-dot ${i<(started?4:p.scriptApproved?3:1)?'done':''}"></i><div><div class="timeline-title">${s}</div><div class="timeline-meta">${i<(started?4:p.scriptApproved?3:1)?'当前项目上游条件已满足':'等待当前项目上游依赖'}</div></div></div>`).join('')}</div></div>
 <div class="card"><div class="card-title">项目资源与成本观察</div><div class="kpi-line"><span>计划集数</span><b>${p.episodes}</b></div><div class="kpi-line"><span>已完成集数</span><b>${p.done||0}</b></div><div class="kpi-line"><span>当前累计成本</span><b>¥${(p.cost||0).toLocaleString()}</b></div><div class="kpi-line"><span>质量评分</span><b>${p.quality||'待检测'}</b></div><div class="notice warn section-gap">达到预算阈值或模型不可用时，系统应暂停受影响任务并通知员工决策，不静默超额消耗。</div></div></div>`);
}},
{path:'pipeline/exceptions',title:'异常处置中心',icon:'!',badge:'1',permission:'pipeline',render(){
 const p=App.project();if(!p||!p.status.includes('异常'))return UI.page('AI ORCHESTRATION / EXCEPTIONS','当前项目暂无待处置异常','异常中心仅展示当前选择项目中需要人工决策的生产异常。','',`<div class="card">${UI.empty('暂无待处置异常','切换到存在异常状态的项目，或等待生产任务触发异常。')}</div>`);
 return UI.page('AI ORCHESTRATION / EXCEPTIONS','生产异常处置','只将必须人工决策的异常交给员工；恢复后由 AI 继续执行受影响任务。','',`
 <div class="grid grid-3">${UI.metric('异常项目',UI.esc(p.title),'项目编号 '+UI.esc(p.id),'!')}${UI.metric('当前阶段',p.stage||'待定位','受影响任务已暂停','↻')}${UI.metric('当前状态',p.status,'等待人工决策','✓')}</div>
 <div class="card section-gap"><div class="card-head"><div><div class="card-title">异常事件 · ${UI.esc(p.title)}</div><div class="card-sub mono">${UI.esc(p.id)} / ${UI.esc(p.stage||'生产任务')}</div></div>${UI.tag(p.exceptionResolved?'已恢复':'待人工处置',p.exceptionResolved?'green':'red')}</div>
 <div class="grid grid-2"><div><div class="eyebrow">FAILURE CONTEXT</div><p class="small" style="line-height:1.8">当前项目的生产阶段出现异常。系统应暂停受影响任务，保留已完成资产，并避免影响其他项目生产。</p><div class="kpi-line"><span>异常项目</span><b>${UI.esc(p.title)}</b></div><div class="kpi-line"><span>失败节点</span><b>${UI.esc(p.stage||'待定位')}</b></div><div class="kpi-line"><span>影响集数</span><b>${p.episodes} 集计划</b></div></div>
 <div><div class="eyebrow">AVAILABLE DECISION</div><div class="callout"><div class="callout-icon">↻</div><div><strong>切换备用能力并恢复任务</strong><p>保留旧版本资产和生产记录；恢复动作只作用于当前项目。</p></div></div><div class="section-gap">${UI.btn(p.exceptionResolved?'任务已恢复':'确认恢复当前项目任务','exception:resolve','btn-lime')}</div></div></div></div>`);
}},
{path:'pipeline/shots',title:'镜头生产单元',icon:'▧',permission:'pipeline',render(){
 const p=App.project();if(!p)return UI.page('AI DIRECTOR / SHOT UNITS','尚未选择项目','选择项目后查看其镜头生产单元。','',`<div class="card">${UI.empty('没有可用项目','当前身份没有可访问的项目。')}</div>`);
 const total=p.shotCount||p.episodes*8,done=Math.min(total,Math.round(total*(p.done||0)/Math.max(p.episodes,1))),pending=total-done;
 return UI.page('AI DIRECTOR / SHOT UNITS','镜头生产单元','Shot Unit 是导演规划与 AI 视频生产之间的核心业务对象。',UI.btn('查看生产调度','go:pipeline/board','btn'),`
 <div class="grid grid-3">${UI.metric('当前项目',UI.esc(p.title),UI.esc(p.id),'▧')}${UI.metric('镜头总量',total,'按当前项目规划统计','◌')}${UI.metric('已完成 / 待生成',done+' / '+pending,'演示进度与项目集数关联','✓')}</div>
 <div class="card section-gap"><div class="toolbar"><b class="small">镜头清单 · 当前项目</b><select class="field" style="width:auto" id="shot-filter"><option value="all">全部状态</option><option value="done">已完成</option><option value="pending">待生成</option></select></div><div class="shot-grid">${Array.from({length:6},(_,i)=>{const isDone=i<Math.min(6,Math.round(6*done/Math.max(total,1)));return `<article class="shot"><div class="shot-art"><span>SHOT / ${UI.esc(p.id)} / ${String(i+1).padStart(2,'0')}</span></div><div class="shot-body"><div class="shot-title">镜头生产单元 ${String(i+1).padStart(2,'0')}</div><div class="shot-meta">${isDone?'已完成 · 待最终抽检':'等待上游任务与资源'}</div></div></article>`;}).join('')}</div></div>`);
}}
]});